const producerPhases = [];
const render = (i, observe = false) => {
    if (!observe) {
        draw(i);
        mod._softgl_read_rgba8(ctx);
        return;
    }
    mod._sg_prepack_diag_reset();
    const frameStart = performance.now();
    draw(i);
    mod._softgl_read_rgba8(ctx);
    const frameEnd = performance.now();
    const calls = Array.from({length:7}, (_, j) => mod._sg_prepack_diag_read(j));
    const elapsedMs = Array.from({length:7}, (_, j) => mod._sg_prepack_diag_read(j + 7));
    const counts = Array.from({length:34}, (_, j) => mod._sg_prepack_diag_read(j + 2*7));
    producerPhases.push({frame:i, angle:(i % frames)*360/frames,
        frameStart, frameEnd, frameElapsedMs:frameEnd-frameStart, calls, elapsedMs, counts});
};

